package dev.typeahead;
import dev.typeahead.core.*;import java.time.*;import java.util.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.data.redis.core.StringRedisTemplate;import tools.jackson.databind.json.JsonMapper;import io.micrometer.core.instrument.MeterRegistry;
@RestController @RequestMapping("/api/v1") class Api {
 private final CacheWriter cacheWriter;private final SingleFlight flights=new SingleFlight();private final ShardGateway gateway;private final Analytics analytics;private final Corpus corpus;private final StringRedisTemplate redis;private final JsonMapper json;private final MeterRegistry metrics;
 Api(Corpus c,StringRedisTemplate r,JsonMapper j,MeterRegistry m,Analytics a,ShardGateway gateway,CacheWriter cacheWriter){this.cacheWriter=cacheWriter;this.gateway=gateway;analytics=a;corpus=c;redis=r;json=j;metrics=m;}
 private String tenant(Jwt jwt){if(jwt==null)return "public";String t=jwt.getClaimAsString("tenant");if(t==null || !t.matches("[a-zA-Z0-9_-]{1,64}"))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Tenant claim required");return t;}
 private String subject(Jwt jwt){if(jwt==null || jwt.getSubject()==null || jwt.getSubject().isBlank() || jwt.getSubject().length()>256)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Subject claim required");return jwt.getSubject();}
 record Suggestion(String id,String text,String type,double score,List<List<Integer>> highlightRanges){}
 record Response(String query,String normalizedQuery,String indexVersion,List<Suggestion> suggestions,Instant generatedAt){}
 @GetMapping("/autocomplete") Response search(@RequestParam(defaultValue="") String prefix,@RequestParam(defaultValue="10") int limit,@RequestParam(defaultValue="*") String category,@RequestParam(defaultValue="*") String language,@RequestParam(defaultValue="false") boolean fuzzy,@AuthenticationPrincipal Jwt jwt){long start=System.nanoTime();if(corpus.owner>=0 && !gateway.enabled())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Use the shard coordinator");if(start-corpus.confirmedAt>3_000_000_000L)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Index freshness cannot be verified");if(prefix.length()>128 || limit<1 || limit>20 || category.length()>64 || language.length()>32)throw new IllegalArgumentException("Invalid query bounds");String q=Normalizer.normalize(prefix);String t=tenant(jwt);var snapshot=corpus.current.get();var index=snapshot.indexes().get(new Corpus.Scope(t,category,language));String key="ac:"+snapshot.version()+":"+Base64.getUrlEncoder().encodeToString((t+"\0"+category+"\0"+language+"\0"+q+"\0"+limit).getBytes(java.nio.charset.StandardCharsets.UTF_8));List<Term> terms=null;
 // Cache IDs only; resolve against this immutable snapshot, never deserialize authority from Redis.
 try(Stage stage=new Stage("redis.get")){String hit=redis.opsForValue().get(key);metrics.counter("autocomplete.cache", "result",hit==null?"miss":"hit").increment();if(hit!=null){terms=Arrays.stream(json.readValue(hit,String[].class)).limit(limit).map(id->snapshot.terms().get(t+"\0"+id)).filter(Objects::nonNull).filter(x->x.active() && Normalizer.normalize(x.text()).startsWith(q) && (category.equals("*") || category.equals(x.category())) && (language.equals("*") || language.equals(x.language()))).sorted(index==null?TrieIndex.ORDER:index.order()).toList();}}catch(Exception e){metrics.counter("autocomplete.cache.errors").increment();}
 if(terms==null){terms=flights.resolve(key,()->{List<Term> loaded=gateway.enabled()?gateway.lookup(snapshot,new Corpus.Scope(t,category,language),q,limit,false,corpus.shards):index==null?List.of():index.prefix(q,limit);cacheWriter.put(key,json.writeValueAsString(loaded.stream().map(Term::id).toList()));return loaded;});}

 if(fuzzy && terms.isEmpty() && index!=null){terms=gateway.enabled()?gateway.lookup(snapshot,new Corpus.Scope(t,category,language),q,limit,true,corpus.shards):index.fuzzy(q,limit);metrics.counter("autocomplete.fuzzy").increment();}
 var out=terms.stream().map(x->new Suggestion(x.id(),x.text(),x.type(),index==null?x.score():index.score(x),q.isEmpty() || !Normalizer.normalize(x.text()).startsWith(q)?List.<List<Integer>>of():List.of(List.of(0,Normalizer.highlightEnd(x.text(),q))))).toList();metrics.timer("autocomplete.lookup").record(System.nanoTime()-start,java.util.concurrent.TimeUnit.NANOSECONDS);return new Response(prefix,q,"v"+snapshot.version(),out,Instant.now());}
 record Context(String prefix,Integer limit,String category,String language,boolean fuzzy){}
 @PostMapping("/autocomplete/contextual") Response contextual(@RequestBody Context c,@AuthenticationPrincipal Jwt jwt){return search(c.prefix()==null?"":c.prefix(),c.limit()==null?10:c.limit(),c.category()==null?"*":c.category(),c.language()==null?"*":c.language(),c.fuzzy(),jwt);}
 @GetMapping("/autocomplete/trending") Response trending(@AuthenticationPrincipal Jwt jwt){String t=tenant(jwt);var snapshot=corpus.current.get();return new Response("","","v"+snapshot.version(),analytics.trending(t).stream().map(x->new Suggestion(x.id(),x.text(),x.type(),x.score(),List.of())).toList(),Instant.now());}
 @GetMapping("/autocomplete/recent") List<Term> recent(@AuthenticationPrincipal Jwt jwt){return analytics.recent(tenant(jwt),subject(jwt));}
 @GetMapping("/autocomplete/health") Map<String,Object> health(){if(System.nanoTime()-corpus.confirmedAt>3_000_000_000L)throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Index stale");return Map.of("status","UP","version",corpus.current.get().version());}
 @GetMapping("/admin/index/status") Map<String,Object> status(@AuthenticationPrincipal Jwt jwt){var s=corpus.current.get();return Map.of("version",s.version(),"terms",s.terms().values().stream().filter(x->x.tenant().equals(tenant(jwt))).count(),"normalization",Normalizer.VERSION,"serving",corpus.indexStatus());}
 @GetMapping("/admin/suggestions") List<Term> list(@RequestParam(defaultValue="0") int offset,@AuthenticationPrincipal Jwt jwt){if(offset<0 || offset>100000)throw new IllegalArgumentException("Invalid offset");return corpus.list(tenant(jwt),offset);}
 @PostMapping("/admin/suggestions") Term create(@RequestBody Term term,@AuthenticationPrincipal Jwt jwt){if(!term.tenant().equals(tenant(jwt)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(term.category()==null || term.language()==null || term.category().equals("*") || term.language().equals("*"))throw new IllegalArgumentException("Explicit category and language required");corpus.save(term);return term;}
 @PatchMapping("/admin/suggestions/{id}") Term update(@PathVariable String id,@RequestBody Map<String,Object> patch,@AuthenticationPrincipal Jwt jwt){
  return corpus.patch(tenant(jwt),id,patch);
 }

 @DeleteMapping("/admin/suggestions/{id}") void delete(@PathVariable String id,@AuthenticationPrincipal Jwt jwt){corpus.delete(tenant(jwt),id);}
 @PostMapping("/admin/index/rebuild") Map<String,Object> rebuild(@AuthenticationPrincipal Jwt jwt){corpus.rebuild();return status(jwt);}
 @PostMapping("/admin/suggestions/import") Map<String,Object> bulk(@RequestBody List<Term> terms,@AuthenticationPrincipal Jwt jwt){if(terms.size()>1000)throw new IllegalArgumentException("Maximum 1000 terms");for(Term term:terms){validateTerm(term,tenant(jwt));}corpus.importTerms(tenant(jwt),terms);return Map.of("imported",terms.size());}
 private void validateTerm(Term term,String tenant){if(!term.tenant().equals(tenant))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(term.category()==null || term.language()==null || term.category().equals("*") || term.language().equals("*"))throw new IllegalArgumentException("Explicit category/language required");}
 @GetMapping("/admin/index/versions") List<Corpus.Version> versions(@AuthenticationPrincipal Jwt jwt){return corpus.versions(tenant(jwt));}
 @PostMapping({"/admin/index/{version}/rollback","/admin/index/{version}/activate"}) Map<String,Object> rollback(@PathVariable long version,@AuthenticationPrincipal Jwt jwt){corpus.rollback(tenant(jwt),version);return status(jwt);}
 @PostMapping("/autocomplete/events") Map<String,Object> event(@RequestBody Analytics.Event event,@AuthenticationPrincipal Jwt jwt){if(jwt==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return Map.of("accepted",analytics.record(tenant(jwt),subject(jwt),event));}
 @DeleteMapping("/autocomplete/events") void erase(@AuthenticationPrincipal Jwt jwt){if(jwt==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);analytics.erase(tenant(jwt),subject(jwt));}
 @GetMapping("/admin/analytics/queries") List<Map<String,Object>> queries(@AuthenticationPrincipal Jwt jwt){return analytics.queries(tenant(jwt),false);}
 @GetMapping("/admin/analytics/zero-results") List<Map<String,Object>> zeros(@AuthenticationPrincipal Jwt jwt){return analytics.queries(tenant(jwt),true);}
 record Policy(double popularityWeight){}
 @GetMapping("/admin/ranking/policies") Policy policy(@AuthenticationPrincipal Jwt jwt){return new Policy(corpus.weight(tenant(jwt)));}
 @PatchMapping("/admin/ranking/policies/{id}") Policy policy(@PathVariable String id,@RequestBody Policy policy,@AuthenticationPrincipal Jwt jwt){if(!id.equals("default"))throw new ResponseStatusException(HttpStatus.NOT_FOUND);corpus.policy(tenant(jwt),policy.popularityWeight());return policy;}
 @ExceptionHandler(IllegalStateException.class) ResponseEntity<ProblemDetail> capacity(IllegalStateException e){return ResponseEntity.status(503).body(ProblemDetail.forStatusAndDetail(HttpStatus.SERVICE_UNAVAILABLE,"Index capacity or traversal budget exceeded"));}
 @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<ProblemDetail> invalid(IllegalArgumentException e){return ResponseEntity.badRequest().body(ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST,e.getMessage()));}
}
